<?php
declare(strict_types=1);
namespace TempNumber;
require_once __DIR__.'/AccountMail.php';
final class GoogleAuth {
 private static function request(string $url,array $fields=[],?string $token=null):array {$c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>15]);if($fields){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,http_build_query($fields));}if($token)curl_setopt($c,CURLOPT_HTTPHEADER,['Authorization: Bearer '.$token]);$raw=curl_exec($c);$status=curl_getinfo($c,CURLINFO_RESPONSE_CODE);curl_close($c);$data=$raw?json_decode($raw,true):null;if($status!==200||!is_array($data))fail('GOOGLE_UNAVAILABLE','Google sign-in could not be completed. Please try again.',503);return $data;}
 public static function start():never {if(!env('GOOGLE_CLIENT_ID')||!env('GOOGLE_CLIENT_SECRET'))fail('GOOGLE_UNAVAILABLE','Google sign-in is not configured.',503);$ref=strtoupper(trim((string)($_GET['ref']??'')));$referrer=$ref!==''?one("SELECT id FROM users WHERE UPPER(referral_code)=? AND status='active'",[$ref]):null;if($ref!==''&&!$referrer)fail('INVALID_REFERRAL','That referral code was not found.');$state=id();$verifier=bin2hex(random_bytes(48));query('INSERT INTO oauth_states (state_hash,verifier,expires_at,referred_by) VALUES (?,?,?,?)',[hash('sha256',$state),$verifier,gmdate('Y-m-d H:i:s',time()+600),$referrer['id']??null]);setcookie('tn_oauth',$state,['expires'=>time()+600,'path'=>'/','secure'=>env('APP_ENV')==='production','httponly'=>true,'samesite'=>'Lax']);$challenge=rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'=');$url='https://accounts.google.com/o/oauth2/v2/auth?'.http_build_query(['client_id'=>env('GOOGLE_CLIENT_ID'),'redirect_uri'=>env('APP_URL').'/api/backend/auth/google/callback','response_type'=>'code','scope'=>'openid email profile','state'=>$state,'code_challenge'=>$challenge,'code_challenge_method'=>'S256']);header('Location: '.$url, true,302);exit;}
 public static function callback():never {$state=(string)($_GET['state']??'');if(!$state||!hash_equals($_COOKIE['tn_oauth']??'',$state))fail('INVALID_STATE','Google sign-in state is invalid.',400);$r=tx(function()use($state){$row=one('SELECT * FROM oauth_states WHERE state_hash=? AND expires_at>?'.lockSuffix(),[hash('sha256',$state),now()]);if(!$row)fail('INVALID_STATE','Google sign-in expired. Please try again.',400);query('DELETE FROM oauth_states WHERE state_hash=?',[hash('sha256',$state)]);return $row;});$tokens=self::request('https://oauth2.googleapis.com/token',['code'=>(string)($_GET['code']??''),'client_id'=>env('GOOGLE_CLIENT_ID'),'client_secret'=>env('GOOGLE_CLIENT_SECRET'),'redirect_uri'=>env('APP_URL').'/api/backend/auth/google/callback','grant_type'=>'authorization_code','code_verifier'=>$r['verifier']]);$profile=self::request('https://openidconnect.googleapis.com/v1/userinfo',[],(string)$tokens['access_token']);if(empty($profile['sub'])||empty($profile['email_verified'])||!filter_var($profile['email']??'',FILTER_VALIDATE_EMAIL))fail('UNVERIFIED_EMAIL','Google did not verify your email address.',403);$identity=one("SELECT u.* FROM oauth_identities i JOIN users u ON u.id=i.user_id WHERE i.provider='google' AND i.subject=?",[$profile['sub']]);if(!$identity){if(one('SELECT id FROM users WHERE email=?',[strtolower($profile['email'])]))fail('ACCOUNT_EXISTS','Sign in using your existing email and password. Automatic account linking is disabled.',409);$uid=id();tx(function()use($uid,$profile,$r){query('INSERT INTO users (id,name,email,password_hash,referral_code,referred_by,created_at) VALUES (?,?,?,?,?,?,?)',[$uid,mb_substr($profile['name']??'Customer',0,120),strtolower($profile['email']),password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),strtoupper(substr(id(),0,10)),$r['referred_by']??null,now()]);query('INSERT INTO wallets (user_id) VALUES (?)',[$uid]);AccountMail::enqueue($uid,'welcome');query("INSERT INTO oauth_identities (provider,subject,user_id) VALUES ('google',?,?)",[$profile['sub'],$uid]);});$identity=one('SELECT * FROM users WHERE id=?',[$uid]);}if($identity['status']!=='active')fail('FORBIDDEN','This account is disabled.',403);session($identity);setcookie('tn_oauth','',['expires'=>time()-3600,'path'=>'/','httponly'=>true,'samesite'=>'Lax','secure'=>env('APP_ENV')==='production']);header('Location: '.env('APP_URL').'/dashboard',true,302);exit;}
}
